9.2 Define get function
Defines a function to get the input data and field to be used for creating the percentile map.


code chunk
get.var &lt;- function(vname,df) {
  v &lt;- df[vname] %&gt;% 
    st_set_geometry(NULL)
  v &lt;- unname(v[,1])
  return(v)
}

5 Geocoding

postcodes &lt;- unique(biz_56111$postal_code)

url &lt;- "https://onemap.gov.sg/api/common/elastic/search"


found &lt;-data.frame()
not_found &lt;- data.frame(postcode = character())

for(pc in postcodes) {
  query &lt;- list(
    searchVal = pc,
    returnGeom = "Y",
    getAddrDetails = "Y",
    pageNum = "1"
  )

  res &lt;- GET(url,query = query)
  json &lt;- content(res)

  if(json$found !=0) {
    df &lt;- as.data.frame(json$results,stringAsFactors = FALSE)
    df$input_postcode &lt;- pc
    found &lt;- bind_rows(found,df)
  } else {
    not_found &lt;- bind_rows(not_found,data,frame(postcode = pc))
  }
}
